export const getRefreshTokensUrl = () => {
  return `/auth/refresh`;
};

/**
 * The refresh token is the credential. Returns a new access token and a new refresh token in the body for the web BFF to hold server side (no cookies); the presented token is used up. Presenting a used token again is treated as theft and ends the whole session, so the BFF must serialise refreshes per session. 401 identity.refresh_token_invalid for any token that cannot be used.
 * @summary Exchange a refresh token for new tokens
 */
export const refreshTokens = async (
  refreshTokensRequest: RefreshTokensRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<AuthTokens> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<AuthTokens>(getRefreshTokensUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(refreshTokensRequest),
  });
};

export const getRefreshTokensQueryKey = (
  refreshTokensRequest?: RefreshTokensRequest,
) => {
  return ["POST", `/auth/refresh`, refreshTokensRequest] as const;
};

