export const getSetEducationLevelUrl = () => {
  return `/me/onboarding/level`;
};

/**
 * Saves a draft step; switching level clears the other stage's details. Optional If-Match with the ETag from a previous onboarding response; a stale value returns 409 concurrency_conflict. 403 identity.onboarding_students_only.
 * @summary Choose high school or tertiary (students)
 */
export const setEducationLevel = async (
  setEducationLevelRequest: SetEducationLevelRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<OnboardingState> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<OnboardingState>(getSetEducationLevelUrl(), {
    ...options,
    method: "PUT",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(setEducationLevelRequest),
  });
};

