export const getAcceptConsentsUrl = () => {
  return `/me/consents`;
};

/**
 * Idempotent per version. marketingEmails true opts in, false withdraws. 409 identity.consent_outdated when the versions are not the current ones from getLegalVersions.
 * @summary Accept the current terms and privacy versions
 */
export const acceptConsents = async (
  acceptConsentsRequest: AcceptConsentsRequest,
  options?: Parameters<typeof apiFetch>[1],
): Promise<void> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiFetch<void>(getAcceptConsentsUrl(), {
    ...options,
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...getHeaders(options?.headers),
    },
    body: JSON.stringify(acceptConsentsRequest),
  });
};

export const getAcceptConsentsQueryKey = (
  acceptConsentsRequest?: AcceptConsentsRequest,
) => {
  return ["POST", `/me/consents`, acceptConsentsRequest] as const;
};

